package com.openimage.common; import java.time.*; import java.time.format.*; import java.util.*; public final class RequestIds{private static final ThreadLocal<String>CURRENT=new ThreadLocal<>(); private RequestIds(){} public static String create(){String v="req_"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+"_"+UUID.randomUUID().toString().substring(0,8); CURRENT.set(v); return v;} public static String current(){String v=CURRENT.get(); return v==null?create():v;} public static void clear(){CURRENT.remove();}}
